from solution import topological_sort

def _is_valid_topo(order, graph):
    if order is None:
        return False
    nodes = set()
    for k, deps in graph.items():
        nodes.add(k)
        nodes.update(deps)
    if set(order) != nodes or len(order) != len(nodes):
        return False
    pos = {n: i for i, n in enumerate(order)}
    for src, dsts in graph.items():
        for d in dsts:
            if pos[src] >= pos[d]:
                return False
    return True

def test_linear_chain():
    g = {"a": ["b"], "b": ["c"], "c": []}
    assert _is_valid_topo(topological_sort(g), g)

def test_diamond():
    g = {"a": ["b", "c"], "b": ["d"], "c": ["d"], "d": []}
    assert _is_valid_topo(topological_sort(g), g)

def test_cycle_returns_none():
    g = {"a": ["b"], "b": ["c"], "c": ["a"]}
    assert topological_sort(g) is None

def test_empty():
    assert topological_sort({}) == []

def test_single_node():
    assert topological_sort({"only": []}) == ["only"]
